<?php
declare(strict_types=1);
function rx_sql_split(string$sql):array{$out=[];$buf='';$quote=null;$escape=false;$line=false;$block=false;$n=strlen($sql);for($i=0;$i<$n;$i++){$c=$sql[$i];$next=$i+1<$n?$sql[$i+1]:'';if($line){if($c==="\n"){$line=false;$buf.=$c;}continue;}if($block){if($c==='*'&&$next==='/'){$block=false;$i++;}continue;}if($quote!==null){$buf.=$c;if($escape){$escape=false;continue;}if($c==='\\'){$escape=true;continue;}if($c===$quote)$quote=null;continue;}if(($c==='-'&&$next==='-'&&($i+2>=$n||ctype_space($sql[$i+2])))||$c==='#'){$line=true;if($c==='-')$i++;continue;}if($c==='/'&&$next==='*'){$block=true;$i++;continue;}if($c==="'"||$c==='"'||$c==='`'){$quote=$c;$buf.=$c;continue;}if($c===';'){if(trim($buf)!=='')$out[]=trim($buf);$buf='';continue;}$buf.=$c;}if(trim($buf)!=='')$out[]=trim($buf);return$out;}
